#include "Lumen/Platform/Window.h"

#include "Lumen/Core/Log.h"

#include <volk.h>

#define GLFW_INCLUDE_NONE
#include <GLFW/glfw3.h>

#include <algorithm>
#include <unordered_map>

// Generated by cmake/Shaders.cmake from Lumen/shaders/.
extern const unsigned char g_Shader_fullscreen_vert[];
extern const size_t g_Shader_fullscreen_vert_size;
extern const unsigned char g_Shader_blit_frag[];
extern const size_t g_Shader_blit_frag_size;

namespace Lumen {

	namespace {

		int s_GlfwUsers = 0;

		bool AcquireGlfw()
		{
			if (s_GlfwUsers == 0)
			{
				glfwSetErrorCallback([](int code, const char* description) { LM_ERROR("GLFW error {}: {}", code, description); });
				if (!glfwInit())
					return false;
			}
			s_GlfwUsers++;
			return true;
		}

		void ReleaseGlfw()
		{
			if (--s_GlfwUsers == 0)
				glfwTerminate();
		}

		Key TranslateKey(int glfwKey)
		{
			if (glfwKey >= GLFW_KEY_A && glfwKey <= GLFW_KEY_Z)
				return static_cast<Key>(static_cast<int>(Key::A) + (glfwKey - GLFW_KEY_A));
			if (glfwKey >= GLFW_KEY_0 && glfwKey <= GLFW_KEY_9)
				return static_cast<Key>(static_cast<int>(Key::Num0) + (glfwKey - GLFW_KEY_0));
			if (glfwKey >= GLFW_KEY_F1 && glfwKey <= GLFW_KEY_F12)
				return static_cast<Key>(static_cast<int>(Key::F1) + (glfwKey - GLFW_KEY_F1));
			switch (glfwKey)
			{
				case GLFW_KEY_SPACE:         return Key::Space;
				case GLFW_KEY_ENTER:         return Key::Enter;
				case GLFW_KEY_ESCAPE:        return Key::Escape;
				case GLFW_KEY_TAB:           return Key::Tab;
				case GLFW_KEY_BACKSPACE:     return Key::Backspace;
				case GLFW_KEY_DELETE:        return Key::Delete;
				case GLFW_KEY_LEFT:          return Key::Left;
				case GLFW_KEY_RIGHT:         return Key::Right;
				case GLFW_KEY_UP:            return Key::Up;
				case GLFW_KEY_DOWN:          return Key::Down;
				case GLFW_KEY_LEFT_SHIFT:    return Key::LeftShift;
				case GLFW_KEY_RIGHT_SHIFT:   return Key::RightShift;
				case GLFW_KEY_LEFT_CONTROL:  return Key::LeftControl;
				case GLFW_KEY_RIGHT_CONTROL: return Key::RightControl;
				case GLFW_KEY_LEFT_ALT:      return Key::LeftAlt;
				case GLFW_KEY_RIGHT_ALT:     return Key::RightAlt;
				default:                     return Key::Unknown;
			}
		}

	}

	struct Window::Impl
	{
		GLFWwindow* Handle = nullptr;
		Ref<RenderDevice> Device;
		InputState Input;
		bool VSync = true;

		// Swapchain
		VkSwapchainKHR Swapchain = VK_NULL_HANDLE;
		VkFormat SwapchainFormat = VK_FORMAT_B8G8R8A8_UNORM;
		nvrhi::Format BackbufferFormat = nvrhi::Format::BGRA8_UNORM;
		uint32_t Width = 0;
		uint32_t Height = 0;
		std::vector<nvrhi::TextureHandle> Backbuffers;
		std::vector<nvrhi::FramebufferHandle> Framebuffers;
		VkSemaphore AcquireSemaphore = VK_NULL_HANDLE;
		VkSemaphore PresentSemaphore = VK_NULL_HANDLE;
		uint32_t ImageIndex = 0;
		bool FrameActive = false;
		bool NeedsRecreate = false;

		// Blit pass
		nvrhi::SamplerHandle Sampler;
		nvrhi::BindingLayoutHandle BlitLayout;
		nvrhi::GraphicsPipelineHandle BlitPipeline;
		nvrhi::ShaderHandle FullscreenVs, BlitPs;
		nvrhi::ITexture* LastSource = nullptr;
		nvrhi::BindingSetHandle LastBindings;

		bool CaptureEnabled = false;
		ImageData LastFrame;

		VkDevice GetDevice() const { return static_cast<VkDevice>(Device->GetVkDevice()); }
		VkQueue GetQueue() const { return static_cast<VkQueue>(Device->GetVkQueue()); }

		void DestroySwapchain(bool keepHandle)
		{
			Framebuffers.clear();
			Backbuffers.clear();
			LastBindings = nullptr;
			LastSource = nullptr;
			if (!keepHandle && Swapchain != VK_NULL_HANDLE)
			{
				vkDestroySwapchainKHR(GetDevice(), Swapchain, nullptr);
				Swapchain = VK_NULL_HANDLE;
			}
		}

		bool CreateSwapchain()
		{
			int fbWidth = 0, fbHeight = 0;
			glfwGetFramebufferSize(Handle, &fbWidth, &fbHeight);
			if (fbWidth <= 0 || fbHeight <= 0)
			{
				Width = Height = 0; // minimized
				return true;
			}

			const VkPhysicalDevice physical = static_cast<VkPhysicalDevice>(Device->GetVkPhysicalDevice());
			const VkSurfaceKHR surface = reinterpret_cast<VkSurfaceKHR>(Device->GetVkSurface());

			VkSurfaceCapabilitiesKHR caps{};
			vkGetPhysicalDeviceSurfaceCapabilitiesKHR(physical, surface, &caps);

			uint32_t count = 0;
			vkGetPhysicalDeviceSurfaceFormatsKHR(physical, surface, &count, nullptr);
			std::vector<VkSurfaceFormatKHR> formats(count);
			vkGetPhysicalDeviceSurfaceFormatsKHR(physical, surface, &count, formats.data());
			VkSurfaceFormatKHR chosen{};
			bool found = false;
			for (VkFormat wanted : { VK_FORMAT_B8G8R8A8_UNORM, VK_FORMAT_R8G8B8A8_UNORM })
			{
				for (const VkSurfaceFormatKHR& f : formats)
					if (f.format == wanted && f.colorSpace == VK_COLOR_SPACE_SRGB_NONLINEAR_KHR)
					{
						chosen = f;
						found = true;
						break;
					}
				if (found)
					break;
			}
			if (!found)
			{
				LM_ERROR("The surface supports neither BGRA8 nor RGBA8 UNORM back buffers");
				return false;
			}
			SwapchainFormat = chosen.format;
			BackbufferFormat = chosen.format == VK_FORMAT_B8G8R8A8_UNORM ? nvrhi::Format::BGRA8_UNORM : nvrhi::Format::RGBA8_UNORM;

			VkExtent2D extent = caps.currentExtent;
			if (extent.width == 0xFFFFFFFFu)
			{
				extent.width = std::clamp(static_cast<uint32_t>(fbWidth), caps.minImageExtent.width, caps.maxImageExtent.width);
				extent.height = std::clamp(static_cast<uint32_t>(fbHeight), caps.minImageExtent.height, caps.maxImageExtent.height);
			}

			VkPresentModeKHR presentMode = VK_PRESENT_MODE_FIFO_KHR; // always available, vsynced
			if (!VSync)
			{
				vkGetPhysicalDeviceSurfacePresentModesKHR(physical, surface, &count, nullptr);
				std::vector<VkPresentModeKHR> modes(count);
				vkGetPhysicalDeviceSurfacePresentModesKHR(physical, surface, &count, modes.data());
				for (VkPresentModeKHR mode : { VK_PRESENT_MODE_MAILBOX_KHR, VK_PRESENT_MODE_IMMEDIATE_KHR })
					if (std::find(modes.begin(), modes.end(), mode) != modes.end())
					{
						presentMode = mode;
						break;
					}
			}

			uint32_t imageCount = caps.minImageCount + 1;
			if (caps.maxImageCount > 0)
				imageCount = std::min(imageCount, caps.maxImageCount);

			VkSwapchainCreateInfoKHR info{};
			info.sType = VK_STRUCTURE_TYPE_SWAPCHAIN_CREATE_INFO_KHR;
			info.surface = surface;
			info.minImageCount = imageCount;
			info.imageFormat = chosen.format;
			info.imageColorSpace = chosen.colorSpace;
			info.imageExtent = extent;
			info.imageArrayLayers = 1;
			info.imageUsage = VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT | VK_IMAGE_USAGE_TRANSFER_SRC_BIT | VK_IMAGE_USAGE_TRANSFER_DST_BIT;
			info.imageSharingMode = VK_SHARING_MODE_EXCLUSIVE;
			info.preTransform = caps.currentTransform;
			info.compositeAlpha = (caps.supportedCompositeAlpha & VK_COMPOSITE_ALPHA_OPAQUE_BIT_KHR) ? VK_COMPOSITE_ALPHA_OPAQUE_BIT_KHR : VK_COMPOSITE_ALPHA_INHERIT_BIT_KHR;
			info.presentMode = presentMode;
			info.clipped = VK_TRUE;
			info.oldSwapchain = Swapchain;

			VkSwapchainKHR created = VK_NULL_HANDLE;
			const VkResult result = vkCreateSwapchainKHR(GetDevice(), &info, nullptr, &created);
			if (Swapchain != VK_NULL_HANDLE)
				vkDestroySwapchainKHR(GetDevice(), Swapchain, nullptr);
			Swapchain = VK_NULL_HANDLE;
			if (result != VK_SUCCESS)
			{
				LM_ERROR("vkCreateSwapchainKHR failed ({})", static_cast<int>(result));
				return false;
			}
			Swapchain = created;
			Width = extent.width;
			Height = extent.height;

			vkGetSwapchainImagesKHR(GetDevice(), Swapchain, &count, nullptr);
			std::vector<VkImage> images(count);
			vkGetSwapchainImagesKHR(GetDevice(), Swapchain, &count, images.data());

			for (VkImage image : images)
			{
				nvrhi::TextureDesc desc;
				desc.width = Width;
				desc.height = Height;
				desc.format = BackbufferFormat;
				desc.isRenderTarget = true;
				desc.initialState = nvrhi::ResourceStates::Present;
				desc.keepInitialState = true;
				desc.debugName = "Backbuffer";
				nvrhi::TextureHandle texture = Device->GetDevice()->createHandleForNativeTexture(nvrhi::ObjectTypes::VK_Image, nvrhi::Object(image), desc);
				if (!texture)
					return false;
				Framebuffers.push_back(Device->GetDevice()->createFramebuffer(nvrhi::FramebufferDesc().addColorAttachment(texture)));
				Backbuffers.push_back(std::move(texture));
			}
			return true;
		}

		bool RecreateSwapchain()
		{
			vkDeviceWaitIdle(GetDevice());
			DestroySwapchain(true);
			NeedsRecreate = false;
			return CreateSwapchain();
		}

		bool CreateBlitResources()
		{
			nvrhi::IDevice* gpu = Device->GetDevice();
			Sampler = gpu->createSampler(nvrhi::SamplerDesc().setAllFilters(true).setAllAddressModes(nvrhi::SamplerAddressMode::Clamp));
			FullscreenVs = gpu->createShader(nvrhi::ShaderDesc().setShaderType(nvrhi::ShaderType::Vertex).setDebugName("fullscreen.vert"), g_Shader_fullscreen_vert, g_Shader_fullscreen_vert_size);
			BlitPs = gpu->createShader(nvrhi::ShaderDesc().setShaderType(nvrhi::ShaderType::Pixel).setDebugName("blit.frag"), g_Shader_blit_frag, g_Shader_blit_frag_size);
			BlitLayout = gpu->createBindingLayout(nvrhi::BindingLayoutDesc()
				.setVisibility(nvrhi::ShaderType::Pixel)
				.addItem(nvrhi::BindingLayoutItem::Texture_SRV(0))
				.addItem(nvrhi::BindingLayoutItem::Sampler(0)));

			nvrhi::GraphicsPipelineDesc desc;
			desc.setPrimType(nvrhi::PrimitiveType::TriangleList).setVertexShader(FullscreenVs).setPixelShader(BlitPs).addBindingLayout(BlitLayout);
			desc.renderState.depthStencilState.depthTestEnable = false;
			desc.renderState.depthStencilState.depthWriteEnable = false;
			desc.renderState.rasterState.cullMode = nvrhi::RasterCullMode::None;
			BlitPipeline = gpu->createGraphicsPipeline(desc, Framebuffers.at(0)->getFramebufferInfo());
			return Sampler && FullscreenVs && BlitPs && BlitLayout && BlitPipeline;
		}
	};

	Ref<Window> Window::Create(const Desc& desc)
	{
		if (!AcquireGlfw())
		{
			LM_ERROR("Could not initialize GLFW (is a display available?)");
			return nullptr;
		}

		Ref<Window> window(new Window());
		window->m_Impl = CreateScope<Impl>();
		Impl& impl = *window->m_Impl;
		impl.VSync = desc.VSync;

		glfwWindowHint(GLFW_CLIENT_API, GLFW_NO_API);
		glfwWindowHint(GLFW_RESIZABLE, desc.Resizable ? GLFW_TRUE : GLFW_FALSE);
		glfwWindowHint(GLFW_VISIBLE, desc.Visible ? GLFW_TRUE : GLFW_FALSE);
		impl.Handle = glfwCreateWindow(static_cast<int>(desc.Width), static_cast<int>(desc.Height), desc.Title.c_str(), nullptr, nullptr);
		if (impl.Handle == nullptr)
		{
			LM_ERROR("Could not create the window");
			ReleaseGlfw();
			window->m_Impl.reset();
			return nullptr;
		}
		if (!glfwVulkanSupported())
		{
			LM_ERROR("GLFW cannot find a Vulkan loader");
			return nullptr; // the destructor cleans up
		}

		uint32_t extensionCount = 0;
		const char** extensions = glfwGetRequiredInstanceExtensions(&extensionCount);
		RenderDevice::Desc deviceDesc;
		for (uint32_t i = 0; i < extensionCount; i++)
			deviceDesc.InstanceExtensions.emplace_back(extensions[i]);
		bool surfaceCreatedHere = false;
		GLFWwindow* handle = impl.Handle;
		deviceDesc.CreateSurface = [handle, &surfaceCreatedHere](void* instance) -> uint64_t
		{
			VkSurfaceKHR surface = VK_NULL_HANDLE;
			if (glfwCreateWindowSurface(static_cast<VkInstance>(instance), handle, nullptr, &surface) != VK_SUCCESS)
				return 0;
			surfaceCreatedHere = true;
			return reinterpret_cast<uint64_t>(surface);
		};

		impl.Device = RenderDevice::Create(deviceDesc);
		if (!impl.Device)
			return nullptr;
		if (!surfaceCreatedHere)
		{
			LM_ERROR("A render device already exists without window support (or for another window); create the window first");
			return nullptr;
		}

		// Semaphores for swapchain synchronization.
		VkSemaphoreCreateInfo semaphoreInfo{};
		semaphoreInfo.sType = VK_STRUCTURE_TYPE_SEMAPHORE_CREATE_INFO;
		vkCreateSemaphore(impl.GetDevice(), &semaphoreInfo, nullptr, &impl.AcquireSemaphore);
		vkCreateSemaphore(impl.GetDevice(), &semaphoreInfo, nullptr, &impl.PresentSemaphore);

		if (!impl.CreateSwapchain() || impl.Backbuffers.empty() || !impl.CreateBlitResources())
		{
			LM_ERROR("Could not create the swapchain");
			return nullptr;
		}

		// Event callbacks feed the InputState.
		glfwSetWindowUserPointer(impl.Handle, &impl);
		glfwSetKeyCallback(impl.Handle, [](GLFWwindow* w, int key, int, int action, int)
		{
			if (action == GLFW_REPEAT)
				return;
			static_cast<Impl*>(glfwGetWindowUserPointer(w))->Input.SetKey(TranslateKey(key), action == GLFW_PRESS);
		});
		glfwSetMouseButtonCallback(impl.Handle, [](GLFWwindow* w, int button, int action, int)
		{
			if (button < 0 || button > 2)
				return;
			static_cast<Impl*>(glfwGetWindowUserPointer(w))->Input.SetMouseButton(static_cast<MouseButton>(button), action == GLFW_PRESS);
		});
		glfwSetCursorPosCallback(impl.Handle, [](GLFWwindow* w, double x, double y)
		{
			static_cast<Impl*>(glfwGetWindowUserPointer(w))->Input.SetMousePosition({ static_cast<float>(x), static_cast<float>(y) });
		});
		glfwSetScrollCallback(impl.Handle, [](GLFWwindow* w, double, double y)
		{
			static_cast<Impl*>(glfwGetWindowUserPointer(w))->Input.AddScroll(static_cast<float>(y));
		});
		glfwSetWindowFocusCallback(impl.Handle, [](GLFWwindow* w, int focused)
		{
			if (!focused)
				static_cast<Impl*>(glfwGetWindowUserPointer(w))->Input.ReleaseAll();
		});
		glfwSetFramebufferSizeCallback(impl.Handle, [](GLFWwindow* w, int, int)
		{
			static_cast<Impl*>(glfwGetWindowUserPointer(w))->NeedsRecreate = true;
		});
		return window;
	}

	Window::~Window()
	{
		if (!m_Impl)
			return;
		Impl& impl = *m_Impl;
		if (impl.Device)
		{
			vkDeviceWaitIdle(impl.GetDevice());
			// Release every GPU object while the device still exists.
			impl.BlitPipeline = nullptr;
			impl.BlitLayout = nullptr;
			impl.FullscreenVs = nullptr;
			impl.BlitPs = nullptr;
			impl.Sampler = nullptr;
			impl.LastBindings = nullptr;
			impl.DestroySwapchain(false);
			if (impl.AcquireSemaphore != VK_NULL_HANDLE)
				vkDestroySemaphore(impl.GetDevice(), impl.AcquireSemaphore, nullptr);
			if (impl.PresentSemaphore != VK_NULL_HANDLE)
				vkDestroySemaphore(impl.GetDevice(), impl.PresentSemaphore, nullptr);
			impl.Device->GetDevice()->runGarbageCollection();
		}
		impl.Device.reset(); // the device owns the surface and must go before the GLFW window
		if (impl.Handle != nullptr)
			glfwDestroyWindow(impl.Handle);
		ReleaseGlfw();
	}

	const Ref<RenderDevice>& Window::GetRenderDevice() const { return m_Impl->Device; }
	GLFWwindow* Window::GetNativeHandle() const { return m_Impl->Handle; }
	const InputState& Window::GetInput() const { return m_Impl->Input; }
	bool Window::ShouldClose() const { return glfwWindowShouldClose(m_Impl->Handle) != 0; }
	void Window::RequestClose() { glfwSetWindowShouldClose(m_Impl->Handle, GLFW_TRUE); }
	uint32_t Window::GetWidth() const { return m_Impl->Width; }
	uint32_t Window::GetHeight() const { return m_Impl->Height; }
	nvrhi::Format Window::GetBackbufferFormat() const { return m_Impl->BackbufferFormat; }
	void Window::SetCaptureEnabled(bool enabled) { m_Impl->CaptureEnabled = enabled; }
	const ImageData& Window::GetLastFrame() const { return m_Impl->LastFrame; }

	void Window::PollEvents()
	{
		m_Impl->Input.BeginFrame();
		glfwPollEvents();
	}

	bool Window::BeginFrame()
	{
		Impl& impl = *m_Impl;
		LM_ASSERT(!impl.FrameActive, "BeginFrame called twice without EndFrame");

		int fbWidth = 0, fbHeight = 0;
		glfwGetFramebufferSize(impl.Handle, &fbWidth, &fbHeight);
		if (fbWidth <= 0 || fbHeight <= 0)
		{
			impl.Width = impl.Height = 0; // minimized: nothing to draw
			impl.NeedsRecreate = true;
			return false;
		}
		if (impl.NeedsRecreate || impl.Swapchain == VK_NULL_HANDLE || static_cast<uint32_t>(fbWidth) != impl.Width || static_cast<uint32_t>(fbHeight) != impl.Height)
			if (!impl.RecreateSwapchain() || impl.Backbuffers.empty())
				return false;

		for (int attempt = 0; attempt < 2; attempt++)
		{
			const VkResult result = vkAcquireNextImageKHR(impl.GetDevice(), impl.Swapchain, UINT64_MAX, impl.AcquireSemaphore, VK_NULL_HANDLE, &impl.ImageIndex);
			if (result == VK_SUCCESS || result == VK_SUBOPTIMAL_KHR)
			{
				impl.FrameActive = true;
				return true;
			}
			if (result != VK_ERROR_OUT_OF_DATE_KHR || !impl.RecreateSwapchain() || impl.Backbuffers.empty())
				break;
		}
		return false;
	}

	nvrhi::IFramebuffer* Window::GetBackbuffer() const
	{
		return m_Impl->FrameActive ? m_Impl->Framebuffers[m_Impl->ImageIndex].Get() : nullptr;
	}

	void Window::DrawTexture(nvrhi::ICommandList* commandList, nvrhi::ITexture* source)
	{
		Impl& impl = *m_Impl;
		LM_ASSERT(impl.FrameActive, "DrawTexture needs an active frame");
		if (impl.LastSource != source || !impl.LastBindings)
		{
			impl.LastBindings = impl.Device->GetDevice()->createBindingSet(nvrhi::BindingSetDesc()
				.addItem(nvrhi::BindingSetItem::Texture_SRV(0, source))
				.addItem(nvrhi::BindingSetItem::Sampler(0, impl.Sampler)), impl.BlitLayout);
			impl.LastSource = source;
		}

		nvrhi::GraphicsState state;
		state.setPipeline(impl.BlitPipeline)
			.setFramebuffer(impl.Framebuffers[impl.ImageIndex])
			.setViewport(nvrhi::ViewportState().addViewportAndScissorRect(nvrhi::Viewport(static_cast<float>(impl.Width), static_cast<float>(impl.Height))))
			.addBindingSet(impl.LastBindings);
		commandList->setGraphicsState(state);
		nvrhi::DrawArguments args;
		args.vertexCount = 3;
		commandList->draw(args);
	}

	void Window::EndFrame(nvrhi::ICommandList* commandList)
	{
		Impl& impl = *m_Impl;
		LM_ASSERT(impl.FrameActive, "EndFrame without BeginFrame");
		impl.FrameActive = false;

		impl.Device->QueueWaitForSemaphore(reinterpret_cast<uint64_t>(impl.AcquireSemaphore));
		if (!impl.CaptureEnabled)
			impl.Device->QueueSignalSemaphore(reinterpret_cast<uint64_t>(impl.PresentSemaphore));
		impl.Device->GetDevice()->executeCommandList(commandList);

		if (impl.CaptureEnabled)
		{
			// Copy the finished frame to the CPU before it is handed to the presentation engine.
			ImageData frame = impl.Device->ReadTexture(impl.Backbuffers[impl.ImageIndex]);
			if (impl.BackbufferFormat == nvrhi::Format::BGRA8_UNORM)
				for (size_t i = 0; i + 3 < frame.Pixels.size(); i += 4)
					std::swap(frame.Pixels[i], frame.Pixels[i + 2]);
			impl.LastFrame = std::move(frame);

			nvrhi::CommandListHandle signalList = impl.Device->GetDevice()->createCommandList();
			signalList->open();
			signalList->close();
			impl.Device->QueueSignalSemaphore(reinterpret_cast<uint64_t>(impl.PresentSemaphore));
			impl.Device->GetDevice()->executeCommandList(signalList);
		}

		VkPresentInfoKHR present{};
		present.sType = VK_STRUCTURE_TYPE_PRESENT_INFO_KHR;
		present.waitSemaphoreCount = 1;
		present.pWaitSemaphores = &impl.PresentSemaphore;
		present.swapchainCount = 1;
		present.pSwapchains = &impl.Swapchain;
		present.pImageIndices = &impl.ImageIndex;
		const VkResult result = vkQueuePresentKHR(impl.GetQueue(), &present);
		if (result == VK_ERROR_OUT_OF_DATE_KHR || result == VK_SUBOPTIMAL_KHR)
			impl.NeedsRecreate = true;
		vkQueueWaitIdle(impl.GetQueue()); // simple and robust: one frame in flight
		impl.Device->GetDevice()->runGarbageCollection();
	}

	void Window::Present(nvrhi::ITexture* source)
	{
		nvrhi::CommandListHandle commandList = m_Impl->Device->GetDevice()->createCommandList();
		commandList->open();
		DrawTexture(commandList, source);
		commandList->close();
		EndFrame(commandList);
	}

}
